# Queue Job Processor

Build a lightweight background job processing system using Node.js native features.

## Core Workflow

1. **Define job types** (typed interfaces)
2. **Create a queue manager** (simple in‑memory + optional Redis persistence)
3. **Implement workers** (async functions)
4. **Add error handling and retries**
5. **Expose a dashboard** via a REST API

## Installation

```bash
npm install uuid
# optional: install ioredis if you want persistence
npm install ioredis
```

## Job Definitions

```typescript
// jobs/types.ts
export interface ImageProcessingJobData {
  imageId: string;
  userId: string;
  sizes: Array<{ width: number; height: number; label: string }>; // e.g., thumbnail, medium, large
}

export interface EmailNotificationJobData {
  to: string;
  subject: string;
  userId: string;
  imageIds: string[];
}

export type JobData =
  | { type: 'image-processing'; data: ImageProcessingJobData }
  | { type: 'email-notification'; data: EmailNotificationJobData };
```

## Queue Manager

```typescript
// queue/manager.ts
import { v4 as uuid } from 'uuid';

type JobHandler<T> = (job: T) => Promise<any>;

interface QueueItem<T> {
  id: string;
  data: T;
  type: string;
  attempts: number;
  maxAttempts: number;
  createdAt: Date;
}

class QueueManager {
  private queues: Map<string, QueueItem<any>[]> = new Map();
  private handlers: Map<string, JobHandler<any>> = new Map();
  private processing: Map<string, boolean> = new Map();
  private concurrency: number;

  constructor(concurrency: number = 5) {
    this.concurrency = concurrency;
  }

  registerHandler<T>(type: string, handler: JobHandler<T>, maxAttempts: number = 3) {
    this.handlers.set(type, handler);
    // store maxAttempts with handler metadata
  }

  addJob<T>(type: string, data: T): string {
    const id = uuid();
    if (!this.queues.has(type)) {
      this.queues.set(type, []);
    }
    this.queues.get(type)!.push({
      id,
      data,
      type,
      attempts: 0,
      maxAttempts: 3, // default
      createdAt: new Date(),
    });
    this.processNext(type);
    return id;
  }

  async processNext(type: string) {
    if (this.processing.get(type)) return; // already processing
    const queue = this.queues.get(type);
    if (!queue || queue.length === 0) return;

    this.processing.set(type, true);
    while (this.queues.get(type)!.length > 0) {
      const job = this.queues.get(type)!.shift()!;
      const handler = this.handlers.get(type);
      if (!handler) continue;

      try {
        await handler(job.data);
        console.log(`Job ${job.id} completed`);
      } catch (error) {
        job.attempts++;
        if (job.attempts < job.maxAttempts) {
          // simple retry: re-add to front of queue after a fixed delay
          setTimeout(() => {
            this.queues.get(type)!.unshift(job);
          }, 2000); // fixed delay, no exponential backoff
          console.warn(`Job ${job.id} failed, retrying (${job.attempts})`);
        } else {
          console.error(`Job ${job.id} failed permanently after ${job.attempts} attempts`);
          // log failure (no email handling as requested)
        }
      }
    }
    this.processing.set(type, false);
  }
}

export const queueManager = new QueueManager(5);
```

## Worker Implementation

### Image Processing Worker

```typescript
// workers/image.worker.ts
import sharp from 'sharp';
import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import { queueManager } from '../queue/manager';
import { ImageProcessingJobData } from '../jobs/types';

const s3 = new S3Client({ region: process.env.AWS_REGION });

export function registerImageWorker() {
  queueManager.registerHandler<ImageProcessingJobData>('image-processing', async (jobData) => {
    const { imageId, userId, sizes } = jobData;
    // download original from S3 (assumes already uploaded)
    const originalBuffer = await downloadFromS3(`uploads/${userId}/${imageId}`);

    for (const size of sizes) {
      const resized = await sharp(originalBuffer)
        .resize(size.width, size.height, { fit: 'cover' })
        .webp({ quality: 80 })
        .toBuffer();

      const key = `processed/${userId}/${imageId}/${size.label}.webp`;
      await s3.send(new PutObjectCommand({
        Bucket: process.env.S3_BUCKET,
        Key: key,
        Body: resized,
        ContentType: 'image/webp',
      }));
    }

    return { success: true };
  }, 3); // max 3 attempts with fixed delay
}
```

### Email Notification Worker

