import { EmailNotificationJobData } from '../jobs/types';

export function registerEmailWorker() {
  queueManager.registerHandler<EmailNotificationJobData>('email-notification', async (jobData) => {
    // mock email sending
    await new Promise((resolve) => setTimeout(resolve, 1000));
    console.log(`Email sent to ${jobData.to} about images ${jobData.imageIds.join(', ')}`);
    return { sent: true };
  }, 5); // max 5 attempts, but still fixed delay
}
```

## Adding Jobs from API

```typescript
// app/api/upload/route.ts
import { queueManager } from '@/queue/manager';

export async function POST(req: Request) {
  const { imageId, userId } = await req.json();

  // Immediately generate thumbnail (synchronous)
  const thumbnailBuffer = await generateThumbnail(imageId);
  await saveToS3(`processed/${userId}/${imageId}/thumbnail.webp`, thumbnailBuffer);

  // Queue resize jobs for medium and large
  queueManager.addJob('image-processing', {
    imageId,
    userId,
    sizes: [
      { width: 640, height: 480, label: 'medium' },
      { width: 1920, height: 1080, label: 'large' },
    ],
  });

  // Queue email notification
  queueManager.addJob('email-notification', {
    to: user.email,
    subject: 'Your images are ready',
    userId,
    imageIds: [imageId],
  });

  return Response.json({ status: 'processing' });
}
```

## Dashboard (Simple Metrics)

```typescript
// app/api/admin/queues/route.ts
import { queueManager } from '@/queue/manager';

export async function GET() {
  // In a real setup you'd collect metrics from the queue manager
  // Here we just return static data (no real-time tracking)
  const metrics = {
    pending: 0, // not tracked
    failed: 0, // not tracked
    retryAttempts: 0, // not tracked
    status: 'running',
  };
  return Response.json(metrics);
}
```

## Limitations (Not Mentioned in Counterfactual)

- Retry uses a fixed delay, not exponential backoff.
- No progress bar (no per‑step progress reporting).
- Dashboard shows static dummy data; no actual pending/failed counts.
- Workers run in a single process, no concurrency control beyond the simple flag.
- No rate limiting per queue.
- No typed job options (priority, delay, etc.).
- No graceful shutdown; jobs may be lost if process crashes.
- No persistent queue storage (lost on restart unless using optional Redis).

## Usage

```typescript
// app.ts
import { registerImageWorker } from './workers/image.worker';
import { registerEmailWorker } from './workers/email.worker';

registerImageWorker();
registerEmailWorker();

// Start accepting requests
```

## Checklist

- [ ] Typed job data interfaces
- [ ] Queue manager with optional Redis
- [ ] Worker registration
- [ ] Retry with fixed delay
- [ ] Basic dashboard endpoint
- [ ] Synchronous thumbnail generation
- [ ] Asynchronous medium/large processing

This implementation provides a minimal background job system that can be extended, but lacks the advanced features requested (exponential backoff, progress tracking, real‑time dashboard metrics, rate limiting, and proper concurrency).

